<?php $verificationLabels = ['pending' => __('Chờ duyệt'), 'approved' => __('Đã duyệt'), 'rejected' => __('Bị từ chối')]; ?>
<section class="page-section"><div class="container">
<div class="section-title"><div><p class="eyebrow"><?= e(__('QUẢN TRỊ')) ?></p><h1><?= e(__('Xác minh danh tính')) ?></h1><p><?= e(__('Số CCCD đầy đủ chỉ hiển thị khi yêu cầu đang chờ duyệt; sau khi duyệt hoặc từ chối, hệ thống chỉ giữ 4 số cuối.')) ?></p></div><a class="btn btn-ghost text-nowrap" href="<?= e(url('/admin')) ?>"><?= e(__('Về quản trị')) ?></a></div>
<section class="surface-card mb-4" aria-label="<?= e(__('Lọc yêu cầu xác minh')) ?>"><form class="form-row" method="get" action="<?= e(url('/admin/verifications')) ?>"><div class="form-group col-md-4"><label for="verification-status"><?= e(__('Trạng thái')) ?></label><select class="form-control" id="verification-status" name="status"><?php foreach(['pending' => __('Chờ duyệt'), 'approved' => __('Đã duyệt'), 'rejected' => __('Bị từ chối'), '' => __('Tất cả')] as $value => $label): ?><option value="<?= e($value) ?>" <?= $status === $value ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><div class="form-group col-md-6"><label for="verification-query"><?= e(__('Email, họ tên tài khoản hoặc họ tên trên CCCD')) ?></label><input class="form-control" id="verification-query" name="q" maxlength="254" value="<?= e($query) ?>"></div><div class="form-group col-md-2 align-self-end"><button class="btn btn-primary btn-block" type="submit"><?= e(__('Lọc')) ?></button></div></form></section>
<p class="results-summary" role="status"><strong><?= e(__('{count} yêu cầu', ['count'=>count($verifications)])) ?></strong><?= count($verifications) >= 200 ? ' · '.e(__('Chỉ hiển thị 200 yêu cầu đầu tiên, hãy lọc thêm.')) : '' ?></p>
<?php if(!$verifications): ?><div class="empty-state"><h2><?= e(__('Không có yêu cầu phù hợp')) ?></h2><p><?= e($status === 'pending' ? __('Hiện không có yêu cầu nào đang chờ duyệt.') : __('Hãy thử đổi trạng thái hoặc từ khóa tìm kiếm.')) ?></p></div><?php endif; ?>
<?php foreach($verifications as $item): $itemId = (int)$item['id']; ?>
<article class="surface-card mb-3 verification-item" aria-labelledby="verification-<?= $itemId ?>-title">
<div class="section-title compact"><div><h2 class="h5 mb-1" id="verification-<?= $itemId ?>-title"><?= e($item['account_name']) ?></h2><p class="small"><?= e($item['email']) ?> · <?= e(__('Gửi lúc {time}', ['time'=>date('d/m/Y H:i', strtotime((string)$item['created_at']))])) ?></p></div><span class="status status-<?= e($item['status']) ?>"><?= e($verificationLabels[$item['status']] ?? $item['status']) ?></span></div>
<dl class="trust-facts"><dt><?= e(__('Họ tên trên CCCD')) ?></dt><dd><?= e($item['full_name_on_card']) ?></dd><dt><?= e(__('Số điện thoại')) ?></dt><dd><?= e($item['phone']) ?></dd><dt><?= e(__('Số CCCD')) ?></dt><dd class="trust-masked"><?= e($item['id_number']) ?></dd><?php if($item['status'] !== 'pending'): ?><dt><?= e(__('Quyết định')) ?></dt><dd><?= e($item['reviewer_name'] ?? 'Admin') ?> · <?= e(date('d/m/Y H:i', strtotime((string)$item['reviewed_at']))) ?><?php if($item['decision_reason'] !== null): ?> — <?= e($item['decision_reason']) ?><?php endif; ?></dd><?php endif; ?></dl>
<?php if($item['status'] === 'pending' && (int)$item['user_id'] === (int)\Core\Auth::id()): ?>
<p class="small text-muted mt-3 mb-0"><?= e(__('Đây là yêu cầu của chính bạn; một Admin khác cần duyệt.')) ?></p>
<?php elseif($item['status'] === 'pending'): ?>
<form class="mt-3" method="post" action="<?= e(url('/admin/verifications/'.$itemId.'/decide')) ?>"><?= csrf_field() ?><div class="form-group"><label for="verification-reason-<?= $itemId ?>"><?= e(__('Lý do / ghi chú (bắt buộc khi từ chối)')) ?></label><input class="form-control" id="verification-reason-<?= $itemId ?>" name="reason" maxlength="1000"></div><div class="action-row"><button class="btn btn-primary" type="submit" name="decision" value="approved" data-confirm="<?= e(__('Duyệt xác minh cho tài khoản này? Số CCCD sẽ được che sau khi lưu.')) ?>"><?= e(__('Duyệt')) ?></button><button class="btn btn-outline-danger" type="submit" name="decision" value="rejected" data-confirm="<?= e(__('Từ chối yêu cầu này? Người dùng sẽ thấy lý do bạn nhập.')) ?>"><?= e(__('Từ chối')) ?></button></div></form>
<?php endif; ?>
</article>
<?php endforeach; ?>
</div></section>
